	@Test
	void skipsDisabledResponseEncodingDuringNegotiation() {
		String previousValue = System.getProperty(DISABLED_ENCODINGS_PROPERTY);
		System.setProperty(DISABLED_ENCODINGS_PROPERTY, "br");
		try {
			MockHttpServletRequest request = new MockHttpServletRequest("GET", "/rdf4j-server/repositories/mem");
			request.addHeader("Accept-Encoding", "br;q=1.0, zstd;q=0.9, gzip;q=0.1");

			assertThat(HttpCompressionEncoding.acceptedResponseEncoding(request))
					.isEqualTo(HttpCompressionEncoding.ZSTD);
		} finally {
			if (previousValue == null) {
				System.clearProperty(DISABLED_ENCODINGS_PROPERTY);
			} else {
				System.setProperty(DISABLED_ENCODINGS_PROPERTY, previousValue);
			}
		}
	}

	@Test
	void roundTripsBrotliAndZstdResponseBodies() throws Exception {
		byte[] body = "compressed rdf response".getBytes(StandardCharsets.UTF_8);

		assertThat(roundTrip(HttpCompressionEncoding.BROTLI, body)).isEqualTo(body);
		assertThat(roundTrip(HttpCompressionEncoding.ZSTD, body)).isEqualTo(body);
	}

	private static byte[] roundTrip(HttpCompressionEncoding encoding, byte[] body) throws IOException {
		ByteArrayOutputStream compressed = new ByteArrayOutputStream();
		OutputStream outputStream = encoding.compressedOutputStream(compressed);
		outputStream.write(body);
		encoding.finish(outputStream);

		return encoding.decompressedInputStream(new ByteArrayInputStream(compressed.toByteArray())).readAllBytes();
	}

	private static MockHttpServletRequest encodedRequest(HttpCompressionEncoding encoding, String body)
			throws IOException {
		ByteArrayOutputStream compressed = new ByteArrayOutputStream();
		OutputStream output = encoding.compressedOutputStream(compressed);
		output.write(body.getBytes(StandardCharsets.UTF_8));
		encoding.finish(output);
		MockHttpServletRequest request = new MockHttpServletRequest("POST", "/statements");
		request.addHeader("Content-Encoding", encoding.headerValue());
		request.setContent(compressed.toByteArray());
		return request;
	}

	private static HttpCompressionFilter configuredFilter(long requestBytes, long formBytes, double ratio, long grace)
			throws ServletException {
		MockFilterConfig config = new MockFilterConfig();
		config.addInitParameter("maxExpandedRequestBytes", Long.toString(requestBytes));
		config.addInitParameter("maxExpandedFormBytes", Long.toString(formBytes));
		config.addInitParameter("maxExpansionRatio", Double.toString(ratio));
		config.addInitParameter("expansionRatioGraceBytes", Long.toString(grace));
		HttpCompressionFilter filter = new HttpCompressionFilter();
		filter.init(config);
		return filter;
	}

	private static byte[] gzip(String body) throws IOException {
		ByteArrayOutputStream buffer = new ByteArrayOutputStream();
		try (GZIPOutputStream outputStream = new GZIPOutputStream(buffer)) {
			outputStream.write(body.getBytes(StandardCharsets.UTF_8));
		}
		return buffer.toByteArray();
	}

	private static String gunzip(byte[] body) throws IOException {
		try (GZIPInputStream inputStream = new GZIPInputStream(new ByteArrayInputStream(body))) {
			return new String(inputStream.readAllBytes(), StandardCharsets.UTF_8);
		}
	}
